%[text] # BEV System Model - Simulation Case
modelName = "BEV_system_model";
load_system(modelName)
BEV_useBasic %[output:6fcf8571]
VehSpdRef_loadCase_FTP75( ... %[output:group:3bfa8477] %[output:7afa0fbc]
  ModelName = modelName, ... %[output:7afa0fbc]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference") %[output:group:3bfa8477] %[output:7afa0fbc]
simOut = sim(modelName); %[output:1e82a7e5] %[output:7c32be00]
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot(SimData = simData, PlotTemperature = false); %[output:5e81d488]
